    ('343eb8e4-e063-5609-9584-5434af1b4eb6'::uuid, 'Quiz — Puissances rivales et guerres sans front', 'Histoire-Géographie', 'Tle', 'Un monde multipolaire (2001 - ) : de nouveaux types de conflits', '011f6fa6-b4e9-5ca0-8a0e-224aee2ccca5'::uuid),
    ('94a0738e-0697-5df6-9f10-c56dbeacd766'::uuid, 'Quiz — Du traité de Rome au marché unique', 'Histoire-Géographie', 'Tle', 'La création d’une Europe ouverte et d’un marché commun (1957-1993)', '9a09a865-971b-5a42-9f9f-f0b38988447d'::uuid),
    ('671bcb1b-6980-59b6-b25c-0bfefd01e44f'::uuid, 'Quiz — Vingt ans de contestation', 'Histoire-Géographie', 'Tle', 'Le projet européen remis en question : les crises de la coopération européenne', '1f4634d4-f6f3-5175-876d-60dfb9038cc6'::uuid),
    ('42a8d44e-5234-5e8d-acb5-49633d7f5769'::uuid, 'Quiz — L’État se réorganise', 'Histoire-Géographie', 'Tle', 'Le renforcement de la Ve République : décentralisation territoriale et fonctionnelle', '3d3ac0bf-9e3f-5bf7-9eff-19129f29191a'::uuid),
    ('63e09d31-42f5-5e50-80e0-a796bbf1a718'::uuid, 'Quiz — Des principes anciens, des droits neufs', 'Histoire-Géographie', 'Tle', 'L’évolution de la Ve République : défense des principes fondateurs et émergence de nouveaux droits', '349fa176-c587-56c9-b06c-99862e40845a'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
