  FROM (VALUES
    ('0bbb0d1c-9509-59bd-8779-04cabf368c51'::uuid, '69c307b3-ca11-5cf8-ac03-5b6af1615362'::uuid, 'Quand le mur de Berlin s’est-il ouvert ?', 'mcq', '["Le 9 novembre 1989","Le 3 octobre 1990","Le 25 décembre 1991","Le 1er mai 1989"]'::jsonb, 0, 'La réunification allemande suivra le 3 octobre 1990.', 1),
    ('fd7b00a2-fb2e-5b9b-b09a-9a3b6ff3b06a'::uuid, '69c307b3-ca11-5cf8-ac03-5b6af1615362'::uuid, 'L’URSS est officiellement dissoute en…', 'mcq', '["décembre 1991","novembre 1989","janvier 1990","août 1993"]'::jsonb, 0, 'Gorbatchev démissionne le 25 décembre 1991.', 2),
    ('bfd9727b-d4ef-5a9c-bab5-f0eebb05145c'::uuid, '69c307b3-ca11-5cf8-ac03-5b6af1615362'::uuid, 'La *glasnost* désigne la restructuration de l’économie soviétique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La *glasnost* est la transparence ; la restructuration est la *perestroïka*.', 3),
