    ('12ece252-d528-5291-957c-4efd27b150fb'::uuid, '69c307b3-ca11-5cf8-ac03-5b6af1615362'::uuid, 'L’Allemagne est réunifiée moins d’un an après l’ouverture du Mur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Novembre 1989 → 3 octobre 1990.', 5),
    ('6a2ff0aa-dc02-5f06-823c-39bea132d2a5'::uuid, '69c307b3-ca11-5cf8-ac03-5b6af1615362'::uuid, 'En 1999, l’OTAN intervient…', 'mcq', '["Au Kosovo","En Tchétchénie","En Géorgie","En Ukraine"]'::jsonb, 0, 'Campagne aérienne contre la Serbie de Milošević.', 6),
    ('ce44f0f7-0b2e-57ec-9a73-7c532b684d28'::uuid, '69c307b3-ca11-5cf8-ac03-5b6af1615362'::uuid, 'L’UE s’élargit à dix nouveaux États en…', 'mcq', '["2004","1995","1999","2007"]'::jsonb, 0, 'Le plus grand élargissement de son histoire, surtout vers l’Est.', 7),
    ('1091cb20-897c-51a5-9229-e8f986c6e328'::uuid, '69c307b3-ca11-5cf8-ac03-5b6af1615362'::uuid, 'La transition vers l’économie de marché s’est faite sans coût social.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La « thérapie de choc » a provoqué chute de la production et chômage de masse.', 8),
    ('85b6cba8-1f8d-56ee-bb8c-edd72defa3d3'::uuid, '2d431294-e36a-53c6-ab06-84493a2ab372'::uuid, 'Les accords d’Oslo sont signés en…', 'mcq', '["1993","1979","1987","2000"]'::jsonb, 0, 'Ils créent l’Autorité palestinienne et esquissent deux États.', 1),
    ('348999aa-02f8-5a49-934f-e153beb58e26'::uuid, '2d431294-e36a-53c6-ab06-84493a2ab372'::uuid, 'La guerre du Golfe de 1991 est menée…', 'mcq', '["Par une coalition sous mandat de l’ONU","Par les États-Unis seuls","Par l’OTAN sans mandat","Par la Ligue arabe"]'::jsonb, 0, 'Après l’invasion du Koweït par l’Irak.', 2),
    ('86af06fb-151f-5368-a4ce-188c0284e987'::uuid, '2d431294-e36a-53c6-ab06-84493a2ab372'::uuid, 'L’invasion de l’Irak en 2003 a reçu l’aval du Conseil de sécurité de l’ONU.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle s’est faite sans mandat ; la France s’y est opposée.', 3),
    ('1c273338-7f8c-5816-a06e-fbd5e7186057'::uuid, '2d431294-e36a-53c6-ab06-84493a2ab372'::uuid, 'Que désigne l’Intifada ?', 'mcq', '["Le soulèvement palestinien","Un parti politique israélien","Un accord de paix","Une organisation pétrolière"]'::jsonb, 0, 'La première éclate en 1987, la seconde en 2000.', 4),
    ('498243cd-e986-596c-abb8-32de6c9ca28f'::uuid, '2d431294-e36a-53c6-ab06-84493a2ab372'::uuid, 'La révolution iranienne a lieu en 1979.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle contribue au second choc pétrolier la même année.', 5),
